    eyex: {"palm": ["Palms over the eyes", "Rub your palms together until warm, then cup them over your closed eyes without pressing. Breathe slowly and enjoy the darkness.", "Rub your palms warm and cover your closed eyes. Breathe slowly."], "blink": ["Blinking", "Blink loosely and quickly about twenty times, then close your eyes for a few seconds. Do not squeeze the eyelids.", "Blink loosely and quickly, then rest with your eyes closed."], "updown": ["Up and down", "Keep your head still. Slowly look up as far as is comfortable, then down. Repeat five times, breathing evenly.", "Head still: slowly look up, then down."], "side": ["Right and left", "Head still. Slowly look right, then left, without straining at the far points. Five times.", "Slowly look right, then left."], "diag": ["Diagonals", "Look up to the right, then down to the left; then up to the left and down to the right. Slowly, three times each way.", "Look diagonally: up right, down left, then the other way."], "circle": ["Circles", "Draw a slow, large circle with your gaze: three times clockwise, three times anticlockwise. Stop if you feel dizzy.", "A slow, large circle with your gaze, then the other way."], "eight": ["Lying eight", "Imagine a large lying figure eight in front of you and trace it slowly with your gaze, several times.", "Trace a lying figure eight with your gaze."], "focus": ["Near and far", "Hold your thumb about 25 cm in front of your face. Look at it for a few seconds, then at a distant object. Alternate ten times, calmly.", "Look at your thumb, then at a distant point, in turn."], "far": ["Looking into the distance", "Look out of the window or at the farthest point of the room (at least 6 metres away) and rest your gaze there for 20 seconds.", "Look at a distant point and rest your gaze there."], "rest": ["Rest", "Warm palms over the closed eyes again. Notice your face and forehead relaxing.", "Warm palms over your closed eyes. Relax your face."]},
